23	public interface OwnerMapper {
24	
25	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
26	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
27	    @Mapping(target = "checkDigit", expression = "java(formatCheckDigit(owner))")
28	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
29	    @Mapping(target = "membershipLevel", expression = "java(formatMembershipLevel(owner))")
30	    @Mapping(target = "locality", expression = "java(formatLocality(owner))")
31	    @Mapping(target = "bulkSignupWarning", expression = "java(formatBulkSignupWarning(owner))")
32	    @Mapping(target = "contactPreference", expression = "java(formatContactPreference(owner))")
33	    @Mapping(target = "ageBand", expression = "java(formatAgeBand(owner))")
34	    OwnerDto toOwnerDto(Owner owner);
35	
36	    /**
37	     * Derive an owner's age band from its {@code birthDate}, measured as the owner's age in whole
38	     * years on its {@code registrationDate}: {@code "MINOR"} when under 18, {@code "ADULT"} from 18
39	     * through 64, and {@code "SENIOR"} at 65 and over. Returns {@code null} when the owner, its
40	     * birth date or its registration date is absent, since the band cannot be derived without both
41	     * dates.
42	     */
43	    default String formatAgeBand(Owner owner) {
44	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
45	            return null;
46	        }
47	        int age = java.time.Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
48	        if (age < 18) {
49	            return "MINOR";
50	        }
51	        if (age < 65) {
52	            return "ADULT";
53	        }
54	        return "SENIOR";
55	    }
56	
57	    /**
58	     * Derive an owner's preferred contact channel from its stored contact details:
59	     * {@code "EMAIL"} when a (non-blank) email address is present, otherwise {@code "PHONE"}.
60	     */
61	    default String formatContactPreference(Owner owner) {
62	        if (owner == null) {
63	            return null;
64	        }
65	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
66	        return hasEmail ? "EMAIL" : "PHONE";
67	    }
68	
69	    /**
70	     * Resolve an owner's bulk-signup warning flag, coalescing a {@code null} stored value
71	     * (e.g. for owners created before the flag existed) to {@code false} so the response
72	     * always carries an explicit boolean.
73	     */
74	    default Boolean formatBulkSignupWarning(Owner owner) {
75	        if (owner == null) {
76	            return null;
77	        }
78	        return Boolean.TRUE.equals(owner.getBulkSignupWarning());
79	    }
80	
81	    /**
82	     * Derive an owner's locality from its region-and-hash identity: the {@code <REGION>} segment
83	     * of the {@code customerCode} (the part before the first hyphen), which is the region code
84	     * derived from the owner's postcode. For an owner that has not yet been assigned a customer
85	     * code, the region is derived directly from the postcode (see {@link Regions#forPostcode}),
86	     * yielding the same value the code would carry. Returns {@code null} only when the owner
87	     * itself is {@code null}.
88	     */
89	    default String formatLocality(Owner owner) {
90	        if (owner == null) {
91	            return null;
92	        }
93	        String code = owner.getCustomerCode();
94	        if (code != null) {
95	            int hyphen = code.indexOf('-');
96	            return hyphen >= 0 ? code.substring(0, hyphen) : code;
97	        }
98	        return Regions.forPostcode(owner.getPostcode());
99	    }
100	
101	    /**
102	     * Determine an owner's membership level, a number from {@code 1} to {@code 3} assigned on
103	     * create. It starts at {@code 1}, gains {@code 1} when an email address is present, and gains
104	     * {@code 1} when the owner has no namesakes (its {@code namesakeCount} is {@code 0}), capped at
105	     * {@code 3}. A null or absent namesake count is treated as not being zero, so it contributes
106	     * nothing. Level {@code 4} is reserved for tenure.
107	     */
108	    default Integer formatMembershipLevel(Owner owner) {
109	        if (owner == null) {
110	            return null;
111	        }
112	        int level = 1;
113	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isEmpty();
114	        if (hasEmail) {
115	            level++;
116	        }
117	        boolean uniqueName = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
118	        if (uniqueName) {
119	            level++;
120	        }
121	        return Math.min(level, 3);
122	    }
123	
124	    /**
125	     * Compute an owner's check digit: a single Luhn check digit (0-9) over the digits
126	     * contained in the owner's {@code customerCode}. Non-digit characters (the region segment
127	     * and any hex letters of the hash) are ignored. Returns {@code null} when the owner or its
128	     * customer code is absent, since the digit cannot be derived without the code.
129	     */
130	    default Integer formatCheckDigit(Owner owner) {
131	        if (owner == null || owner.getCustomerCode() == null) {
132	            return null;
133	        }
134	        String code = owner.getCustomerCode();
135	        int sum = 0;
136	        boolean dbl = true;
137	        for (int i = code.length() - 1; i >= 0; i--) {
138	            char c = code.charAt(i);
139	            if (c < '0' || c > '9') {
140	                continue;
141	            }
142	            int d = c - '0';
143	            if (dbl) {
144	                d *= 2;
145	                if (d > 9) {
146	                    d -= 9;
147	                }
148	            }
149	            sum += d;
150	            dbl = !dbl;
151	        }
152	        return (10 - (sum % 10)) % 10;
153	    }
154	
155	    /**
156	     * Format an owner's membership number as {@code "<customerCode>-M<YY>"}, where {@code YY}
157	     * is the last two digits of the registration date year (e.g. {@code "NSW-3F5A9C2E-M26"}).
158	     * Returns {@code null} when either the customer code or registration date is absent, since
159	     * the number cannot be derived without both.
160	     */
161	    default String formatMembershipNumber(Owner owner) {
162	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
163	            return null;
164	        }
165	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
166	    }
167	
168	    /**
169	     * Format an owner's name as {@code "LastName, FirstName"} from the stored names.
170	     */
171	    default String formatDisplayName(Owner owner) {
172	        if (owner == null) {
173	            return null;
174	        }
175	        return owner.getLastName() + ", " + owner.getFirstName();
176	    }
177	
178	    /**
179	     * Format an owner's initials as the upper-cased first letters of the first and last
180	     * names, dot-separated with a trailing dot, e.g. {@code "J.S."}.
181	     */
182	    default String formatInitials(Owner owner) {
183	        if (owner == null) {
184	            return null;
185	        }
186	        return Character.toUpperCase(owner.getFirstName().charAt(0)) + "."
187	            + Character.toUpperCase(owner.getLastName().charAt(0)) + ".";
188	    }
189	
190	    Owner toOwner(OwnerDto ownerDto);
191	
192	    @Mapping(target = "id", ignore = true)
193	    @Mapping(target = "pets", ignore = true)
194	    @Mapping(target = "householdId", ignore = true)
195	    @Mapping(target = "namesakeCount", ignore = true)
196	    @Mapping(target = "bulkSignupWarning", ignore = true)
