198	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
199	    @Mapping(target = "email", source = "email", qualifiedByName = "normalizeEmail")
200	    Owner toOwner(OwnerFieldsDto ownerDto);
201	
202	    /**
203	     * Normalize a postal address for storage into its canonical form (see
204	     * {@link AddressNormalizer}), so it is persisted and returned the same way regardless of
205	     * the formatting supplied by the caller. {@code @Named} keeps this out of MapStruct's
206	     * automatic method selection, so it only runs where a mapping explicitly references it via
207	     * {@code qualifiedByName}.
208	     */
209	    @Named("normalizeAddress")
210	    default String normalizeAddress(String address) {
211	        return AddressNormalizer.normalize(address);
212	    }
213	
214	    /**
215	     * Normalize a telephone number for storage into E.164 form (see {@link E164Telephone}).
216	     * The requirement that a valid E.164 number can be formed is enforced separately by
217	     * {@code TelephoneValidation}, so for already-validated input this returns the E.164
218	     * string; it is idempotent, so re-normalizing a stored value yields the same value.
219	     * {@code @Named} keeps this out of MapStruct's automatic method selection, so it only
220	     * runs where a mapping explicitly references it via {@code qualifiedByName}.
221	     */
222	    @Named("normalizeTelephone")
223	    default String normalizeTelephone(String telephone) {
224	        return E164Telephone.normalize(telephone);
225	    }
226	
227	    /**
228	     * Normalize an email address for storage by lower-casing it, so it is persisted and
229	     * returned in a canonical form regardless of the casing supplied by the caller.
230	     * Syntactic validity is enforced separately by the {@code @Email} constraint on the DTO.
231	     * {@code @Named} keeps this out of MapStruct's automatic method selection, so it only
232	     * runs where a mapping explicitly references it via {@code qualifiedByName}.
233	     */
234	    @Named("normalizeEmail")
235	    default String normalizeEmail(String email) {
236	        return email == null ? null : email.toLowerCase();
237	    }
238	
239	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
240	
241	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
242	
